4. MODIFY c:\Users\KING\number-academy\vite.config.js — add a server.proxy config to the defineConfig call:
   server: {
     proxy: {
       '/api': {
         target: 'http://localhost:3001',
         changeOrigin: true,
       }
     }
   }
   Insert this at the top level of the config object alongside plugins: [].

5. CREATE c:\Users\KING\number-academy\src\services\ai.js with four exported async functions:

   const BASE_URL = '/api/generate';

   async function callAI(messages) {
     const res = await fetch(BASE_URL, {
       method: 'POST',
       headers: { 'Content-Type': 'application/json' },
       body: JSON.stringify({ messages }),
     });
     if (!res.ok) {
       const err = await res.json().catch(() => ({}));
       throw new Error(err.error || `AI request failed (${res.status})`);
     }
     const data = await res.json();
     return data.choices?.[0]?.message?.content ?? '';
   }

   function buildSystemPrompt() {
     return 'You are an expert Ghanaian Junior High School teacher assistant trained on the NaCCA Common Core Programme (CCP) curriculum. You help teachers plan lessons, design activities, and create assessments aligned to the Ghana National Curriculum.';
   }

   export async function generateLessonPlan({ strand, subStrand, contentStandard, indicators }) {
     // Returns an object with keys: starterActivity, mainLearning, plenary, keyQuestions, resourcesSuggested, homework
     // Prompt instructs to respond with a JSON object containing these exact keys.
   }

   export async function generateActivities({ strand, subStrand, contentStandard, indicators }) {
     // Returns a markdown string of classroom activities
   }

   export async function generateAssessment({ strand, subStrand, contentStandard, indicators }) {
     // Returns a markdown string of formative assessment ideas
   }

   export async function explainIndicator({ indicator, contentStandard, subStrand, strand }) {
     // Returns a markdown string explaining the indicator in plain language for a Ghanaian JHS teacher
   }

   Prompt details for each:
   - generateLessonPlan: system = buildSystemPrompt(). User message = `Create a complete lesson plan for a Ghanaian JHS teacher for the following NaCCA curriculum indicator(s):
     Strand: ${strand.title}
     Sub-Strand: ${subStrand.title}
     Content Standard ${contentStandard.code}: ${contentStandard.description}
     Indicators: ${indicators.map(i => i.code + ': ' + i.description).join('; ')}

     Respond with ONLY a valid JSON object (no markdown fences) with these exact keys: starterActivity, mainLearning, plenary, keyQuestions, resourcesSuggested, homework. Each value is a plain string.`
     Parse the returned string as JSON; if parse fails return { starterActivity: raw, mainLearning:'', plenary:'', keyQuestions:'', resourcesSuggested:'', homework:'' }.

   - generateActivities: user = `Suggest 3–5 engaging classroom activities for a Ghanaian JHS teacher for:
     Content Standard ${contentStandard.code}: ${contentStandard.description}
     Indicators: ${indicators.map(i => i.code + ': ' + i.description).join('; ')}
     Activities should be practical, low-resource, and appropriate for a Ghanaian classroom.`
     Return raw string.

   - generateAssessment: user = `Create formative assessment questions and tasks for a Ghanaian JHS teacher for:
     Content Standard ${contentStandard.code}: ${contentStandard.description}
     Indicators: ${indicators.map(i => i.code + ': ' + i.description).join('; ')}
     Include: 3 oral questions, 2 written tasks, and one group activity.`
     Return raw string.

   - explainIndicator: user = `Explain this NaCCA curriculum indicator in simple terms for a Ghanaian JHS teacher:
     Indicator ${indicator.code}: ${indicator.description}
     (from ${contentStandard.code} under ${subStrand.title}, ${strand.title})
     Briefly explain what learners should be able to do, why it matters, and one quick example to use in class.`
     Return raw string.
